package main

import (
	"encoding/json/jsontext"
	"encoding/json/v2"
	"fmt"
	"regexp"
	"sort"
	"strings"
)

// The A7 corpus is generated by walking an operation's request schema in the bundle (ADR-0004
// "The A7 corpus cases"). This file is the schema walk: a valid instance plus the list of nodes
// to mutate. corpus.go turns nodes into cases and runs them through the router.

type nodeKind int

const (
	nodeObject nodeKind = iota
	nodeUnion
)

// node is one place the corpus mutates: an object (with its members) or a union (its kind).
type node struct {
	kind     nodeKind
	ptr      string
	members  []string        // declared member names, in order
	required map[string]bool // required members
	nullable map[string]bool // members whose schema admits null
}

// instance is a valid value and what the walk found in it.
type instance struct {
	value   any
	nodes   []node
	free    string   // pointer of a string with no enum, format, pattern or const, or ""
	unions  []string // pointers of unions, for variant selection
	variant map[string]int
	unionN  map[string]int // pointer → number of variants
}

type walker struct {
	root map[string]any
	inst *instance
	pick map[string]int
	err  error
}

func (w *walker) fail(ptr, f string, a ...any) {
	if w.err == nil {
		w.err = fmt.Errorf("%s: %s", orRoot(ptr), fmt.Sprintf(f, a...))
	}
}

func orRoot(p string) string {
	if p == "" {
		return "(body)"
	}
	return p
}

func escPtr(s string) string { return strings.ReplaceAll(strings.ReplaceAll(s, "~", "~0"), "/", "~1") }

// requestSchema finds the JSON request schema of an operation in the bundle.
func requestSchema(root map[string]any, path, method, media string) (any, string, bool) {
	paths, _ := root["paths"].(map[string]any)
	item, _ := paths[path].(map[string]any)
	op, _ := item[strings.ToLower(method)].(map[string]any)
	rb, _ := op["requestBody"].(map[string]any)
	content, _ := rb["content"].(map[string]any)
	mt, _ := content[media].(map[string]any)
	s, ok := mt["schema"]
	return s, "#/paths/" + escPtr(path) + "/" + strings.ToLower(method) + "/requestBody/content/" + escPtr(media) + "/schema", ok
}

func (w *walker) resolve(s any) map[string]any {
	for i := 0; i < 32; i++ {
		m, _ := s.(map[string]any)
		ref, ok := m["$ref"].(string)
		if !ok {
			return m
		}
		cur := any(w.root)
		for _, seg := range strings.Split(strings.TrimPrefix(ref, "#/"), "/") {
			seg = strings.ReplaceAll(strings.ReplaceAll(seg, "~1", "/"), "~0", "~")
			cm, _ := cur.(map[string]any)
			cur = cm[seg]
		}
		s = cur
	}
	return nil
}

func typeOf(m map[string]any) (typ string, nullable bool) {
	switch t := m["type"].(type) {
	case string:
		return t, false
	case []any:
		for _, x := range t {
			if s, _ := x.(string); s == "null" {
				nullable = true
			} else if s != "" {
				typ = s
			}
		}
	}
	return typ, nullable
}

func strs(v any) []string {
	var out []string
	l, _ := v.([]any)
	for _, x := range l {
		if s, ok := x.(string); ok {
			out = append(out, s)
		}
	}
	return out
}

func num(m map[string]any, k string) (float64, bool) {
	f, ok := m[k].(float64)
	return f, ok
}

var stringCandidates = []string{"a", "0", "1", "A", "aa", "a0", "x@example.com", "a-b", "a.b", "/a"}

func (w *walker) gen(s any, ptr string, depth int) any {
	if w.err != nil {
		return nil
	}
	if depth > 10 {
		w.fail(ptr, "the schema recurses past depth 10 through required members")
		return nil
	}
	m := w.resolve(s)
	if m == nil {
		w.fail(ptr, "unresolvable schema")
		return nil
	}
	if c, ok := m["const"]; ok {
		return c
	}
	if e, _ := m["enum"].([]any); len(e) > 0 {
		return e[0]
	}
	if all, _ := m["allOf"].([]any); len(all) > 0 {
		merged := map[string]any{}
		props := map[string]any{}
		var req []any
		for _, part := range all {
			pm := w.resolve(part)
			for k, v := range pm {
				switch k {
				case "properties":
					for pk, pv := range v.(map[string]any) {
						props[pk] = pv
					}
				case "required":
					req = append(req, v.([]any)...)
				default:
					merged[k] = v
				}
			}
		}
		merged["properties"], merged["required"] = props, req
		return w.gen(merged, ptr, depth+1)
	}
	if one, _ := m["oneOf"].([]any); len(one) > 0 {
		w.inst.unions = append(w.inst.unions, ptr)
		w.inst.unionN[ptr] = len(one)
		w.inst.nodes = append(w.inst.nodes, node{kind: nodeUnion, ptr: ptr})
		i := w.pick[ptr]
		if i >= len(one) {
			i = 0
		}
		return w.gen(one[i], ptr, depth+1)
	}
	typ, _ := typeOf(m)
	props, _ := m["properties"].(map[string]any)
	if typ == "" && props != nil {
		typ = "object"
	}
	switch typ {
	case "object":
		if len(props) == 0 {
			if ap, ok := m["additionalProperties"].(map[string]any); ok || m["additionalProperties"] != nil && m["additionalProperties"] != false {
				out := map[string]any{}
				if ok {
					out["k"] = w.gen(ap, ptr+"/k", depth+1)
				}
				return out
			}
			w.inst.nodes = append(w.inst.nodes, node{kind: nodeObject, ptr: ptr, required: map[string]bool{}, nullable: map[string]bool{}})
			return map[string]any{}
		}
		n := node{kind: nodeObject, ptr: ptr, required: map[string]bool{}, nullable: map[string]bool{}}
		for _, r := range strs(m["required"]) {
			n.required[r] = true
		}
		names := make([]string, 0, len(props))
		for k := range props {
			names = append(names, k)
		}
		sort.Strings(names)
		out := map[string]any{}
		for _, k := range names {
			n.members = append(n.members, k)
			if _, nl := typeOf(w.resolve(props[k])); nl {
				n.nullable[k] = true
			}
			out[k] = w.gen(props[k], ptr+"/"+escPtr(k), depth+1)
		}
		w.inst.nodes = append(w.inst.nodes, n)
		return out
	case "array":
		n := 1
		if mi, ok := num(m, "minItems"); ok && int(mi) > n {
			n = int(mi)
		}
		if mx, ok := num(m, "maxItems"); ok && int(mx) < n {
			n = int(mx)
		}
		out := []any{}
		for i := 0; i < n; i++ {
			out = append(out, w.gen(m["items"], fmt.Sprintf("%s/%d", ptr, i), depth+1))
		}
		return out
	case "string":
		return w.genString(m, ptr)
	case "integer", "number":
		v, hasMin := num(m, "minimum")
		if x, ok := num(m, "exclusiveMinimum"); ok {
			v, hasMin = x+1, true
		}
		if !hasMin {
			v = 0
			if mx, ok := num(m, "maximum"); ok && mx < 0 {
				v = mx
			}
		}
		if mx, ok := num(m, "maximum"); ok && v > mx {
			v = mx
		}
		return v
	case "boolean":
		return false
	case "null":
		return nil
	}
	w.fail(ptr, "cannot generate an instance for this schema (type %q)", typ)
	return nil
}

func (w *walker) genString(m map[string]any, ptr string) any {
	minLen := 0
	if f, ok := num(m, "minLength"); ok {
		minLen = int(f)
	}
	maxLen := -1
	if f, ok := num(m, "maxLength"); ok {
		maxLen = int(f)
	}
	format, _ := m["format"].(string)
	switch format {
	case "uuid":
		return "00000000-0000-4000-8000-000000000000"
	case "date":
		return "2000-01-01"
	case "date-time":
		return "2000-01-01T00:00:00Z"
	case "email":
		return "a@example.com"
	}
	pat, _ := m["pattern"].(string)
	var re *regexp.Regexp
	if pat != "" {
		var err error
		if re, err = regexp.Compile(pat); err != nil {
			w.fail(ptr, "the pattern %q does not compile in Go", pat)
			return nil
		}
	}
	for _, c := range stringCandidates {
		for len(c) < minLen {
			c += "a"
			if re != nil && !re.MatchString(c) {
				c = strings.Repeat(string(c[0]), minLen)
			}
		}
		if (maxLen < 0 || len(c) <= maxLen) && (re == nil || re.MatchString(c)) {
			if re == nil && format == "" && w.inst.free == "" {
				w.inst.free = ptr
			}
			return c
		}
	}
	w.fail(ptr, "no string satisfies pattern %q with length %d..%d among the generator's candidates", pat, minLen, maxLen)
	return nil
}

// genInstance builds one valid instance, selecting union variants by pick.
func genInstance(root map[string]any, schema any, pick map[string]int) (*instance, error) {
	w := &walker{root: root, pick: pick, inst: &instance{unionN: map[string]int{}}}
	w.inst.value = w.gen(schema, "", 0)
	return w.inst, w.err
}

// at returns the container at a JSON pointer (own syntax: "/a/0/b", ~1 for "/").
func at(v any, ptr string) any {
	if ptr == "" {
		return v
	}
	for _, seg := range strings.Split(ptr[1:], "/") {
		seg = strings.ReplaceAll(strings.ReplaceAll(seg, "~1", "/"), "~0", "~")
		switch c := v.(type) {
		case map[string]any:
			v = c[seg]
		case []any:
			var i int
			fmt.Sscanf(seg, "%d", &i)
			if i >= len(c) {
				return nil
			}
			v = c[i]
		default:
			return nil
		}
	}
	return v
}

// clone deep-copies a generated value.
func clone(v any) any {
	b, _ := json.Marshal(v, json.Deterministic(true))
	var out any
	_ = json.Unmarshal(b, &out)
	return out
}

func encode(v any) []byte {
	b, _ := json.Marshal(v, json.Deterministic(true))
	return b
}

var _ = jsontext.Value(nil)
